// Akzeptiert 1/0, true/false oder "on"/"off" als Eingang.
var p = msg.payload;
var on = (p === 1 || p === true || p === '1' || p === 'on' || p === 'ein');
var value = on ? 1 : 0;

msg.payload = 'dbus -y com.victronenergy.settings'
    + ' /Settings/Devices/tsbuckboost/SeparateTempSensors SetValue ' + value
    + ' && svc -t /service/TsBuckBoost';
msg.tsbbValue = value;
return msg;

msg.payload = msg.tsbbValue === 1
    ? 'Temperaturgeraete eingeschaltet, Treiber startet neu'
    : 'Temperaturgeraete ausgeschaltet, Treiber startet neu';
return msg;
